#!/usr/bin/env node

/**
 * Simple signature verification utility for AgentKit plugins
 * Demonstrates that signatures generated by sign-plugin can be verified
 */

const fs = require('fs')
const crypto = require('crypto')
const path = require('path')

function verifyPluginSignature(pluginFile, signatureFile) {
  console.log('🔍 Verifying plugin signature...')
  
  // Read plugin content and signature
  const pluginContent = fs.readFileSync(pluginFile, 'utf8')
  const signatureData = JSON.parse(fs.readFileSync(signatureFile, 'utf8'))
  
  console.log(`Plugin: ${pluginFile}`)
  console.log(`Algorithm: ${signatureData.algorithm}`)
  
  // Verify content hash
  const currentHash = crypto.createHash('sha256').update(pluginContent).digest('hex')
  if (currentHash !== signatureData.hash) {
    console.log('❌ Plugin content hash mismatch!')
    return false
  }
  console.log('✅ Plugin content hash verified')
  
  // Verify based on algorithm
  if (signatureData.algorithm === 'HMAC-SHA256') {
    return verifyHMACSignature(signatureData, pluginContent)
  } else if (signatureData.algorithm === 'Ed25519') {
    return verifyEd25519Signature(signatureData, pluginContent)
  } else {
    console.log(`❌ Unknown algorithm: ${signatureData.algorithm}`)
    return false
  }
}

function verifyHMACSignature(signatureData, pluginContent) {
  console.log('🔑 Verifying HMAC signature...')
  
  const secret = process.env.AGENTKIT_SIGNING_SECRET
  if (!secret) {
    console.log('❌ AGENTKIT_SIGNING_SECRET environment variable required for HMAC verification')
    return false
  }
  
  // Recreate the signed content
  const signedContent = signatureData.signed
  
  // Generate expected HMAC
  const hmac = crypto.createHmac('sha256', secret)
  hmac.update(signedContent)
  const expectedSignature = hmac.digest('hex')
  
  if (expectedSignature === signatureData.signature) {
    console.log('✅ HMAC signature verified')
    return true
  } else {
    console.log('❌ HMAC signature mismatch')
    return false
  }
}

function verifyEd25519Signature(signatureData, pluginContent) {
  console.log('🔑 Verifying Ed25519 signature...')
  
  // Load the public key
  const keyPath = path.join(require('os').homedir(), '.agentkit', 'keys', 'dev.key')
  if (!fs.existsSync(keyPath)) {
    console.log('❌ Ed25519 key not found. Cannot verify signature.')
    return false
  }
  
  const keyPair = JSON.parse(fs.readFileSync(keyPath, 'utf8'))
  
  // Verify key ID matches
  if (keyPair.keyId !== signatureData.keyId) {
    console.log('❌ Key ID mismatch')
    return false
  }
  
  // Check expiration
  const now = Math.floor(Date.now() / 1000)
  if (signatureData.expires < now) {
    console.log('❌ Signature has expired')
    return false
  }
  
  try {
    // Verify the signature
    const messageBuffer = Buffer.from(signatureData.message)
    const signatureBuffer = Buffer.from(signatureData.signature, 'base64')
    
    const isValid = crypto.verify(null, messageBuffer, keyPair.publicKey, signatureBuffer)
    
    if (isValid) {
      console.log('✅ Ed25519 signature verified')
      return true
    } else {
      console.log('❌ Ed25519 signature invalid')
      return false
    }
  } catch (error) {
    console.log('❌ Error verifying Ed25519 signature:', error.message)
    return false
  }
}

// CLI usage
if (require.main === module) {
  const pluginFile = process.argv[2]
  const signatureFile = process.argv[3] || 'plugin.signed.json'
  
  if (!pluginFile) {
    console.log('Usage: node verify-signature.js <plugin-file> [signature-file]')
    process.exit(1)
  }
  
  const isValid = verifyPluginSignature(pluginFile, signatureFile)
  console.log(isValid ? '\n🎉 Signature verification successful!' : '\n💥 Signature verification failed!')
  process.exit(isValid ? 0 : 1)
}

module.exports = { verifyPluginSignature }